with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PLAN_ID))) as HUB_PRODUCT_HK
        , PARAM_REF as PRODUCT_PARAMETER_SET_REFERENCE
        , cast(null as varchar) as SERVICE_TAX_APPLICABLE_INDICATOR
        , cast(null as varchar) as PARENT_PRODUCT_INDICATOR
        , cast(null as varchar) as NEW_PLAN_NAME_INDICATOR
        , 'BJAZ_BANDHAN_MEDI_CLAM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bandhan_medi_clam') }}
    where (nullif(trim(PLAN_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_PARAMETER_SET_REFERENCE
        , SERTAX_FLAG as SERVICE_TAX_APPLICABLE_INDICATOR
        , PARENT_FLAG as PARENT_PRODUCT_INDICATOR
        , cast(null as varchar) as NEW_PLAN_NAME_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_MST' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_mst') }}
    where (nullif(trim(SCHEME_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , cast(null as varchar) as PRODUCT_PARAMETER_SET_REFERENCE
        , cast(null as varchar) as SERVICE_TAX_APPLICABLE_INDICATOR
        , cast(null as varchar) as PARENT_PRODUCT_INDICATOR
        , NEW_PLANNAME_YN as NEW_PLAN_NAME_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRODUCT_PARAMETER_SET_REFERENCE end) as PRODUCT_PARAMETER_SET_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SERVICE_TAX_APPLICABLE_INDICATOR end) as SERVICE_TAX_APPLICABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARENT_PRODUCT_INDICATOR end) as PARENT_PRODUCT_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEW_PLAN_NAME_INDICATOR end) as NEW_PLAN_NAME_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when PRODUCT_PARAMETER_SET_REFERENCE is not null or SERVICE_TAX_APPLICABLE_INDICATOR is not null or PARENT_PRODUCT_INDICATOR is not null or NEW_PLAN_NAME_INDICATOR is not null
                     then md5(upper(coalesce(cast(PRODUCT_PARAMETER_SET_REFERENCE as varchar), '') || '|' || coalesce(cast(SERVICE_TAX_APPLICABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(PARENT_PRODUCT_INDICATOR as varchar), '') || '|' || coalesce(cast(NEW_PLAN_NAME_INDICATOR as varchar), '')))
                end as SAT_PRODUCT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_DEFINITION_HASHDIFF is not null
